export const CSS = "/* Gleemoji animation styles */\n.gm{display:inline-block;vertical-align:-0.2em;overflow:visible}\n/* ---------- motion ---------- */\n.gm-a{transform-box:fill-box;transform-origin:center;animation-delay:var(--gm-d,0s)}\n.gm-a > *{animation-delay:var(--gm-d,0s)}\n.gm-a.gm-b{transform-box:view-box;transform-origin:64px 118px}\n.gm-b-bounce{animation:gm-bounce 1.6s cubic-bezier(.3,0,.3,1) infinite}\n@keyframes gm-bounce{0%,60%,100%{transform:translateY(0) scale(1,1)}20%{transform:translateY(-10px) scale(.97,1.03)}40%{transform:translateY(0) scale(1.05,.95)}}\n.gm-a.gm-b-shake{transform-origin:64px 64px;animation:gm-shake 1s ease-in-out infinite}\n@keyframes gm-shake{0%,100%{transform:rotate(0)}15%{transform:rotate(-7deg)}30%{transform:rotate(6deg)}45%{transform:rotate(-5deg)}60%{transform:rotate(4deg)}75%{transform:rotate(0)}}\n.gm-b-shiver{animation:gm-shiver .22s linear infinite}\n@keyframes gm-shiver{0%,100%{transform:translateX(0)}25%{transform:translateX(-1.8px)}75%{transform:translateX(1.8px)}}\n.gm-b-sway{animation:gm-sway 2.6s ease-in-out infinite}\n@keyframes gm-sway{0%,100%{transform:rotate(0)}25%{transform:rotate(-6deg)}75%{transform:rotate(6deg)}}\n.gm-a.gm-b-wobble{transform-origin:64px 64px;animation:gm-wobble 3s ease-in-out infinite}\n@keyframes gm-wobble{0%,100%{transform:rotate(0) skewX(0)}25%{transform:rotate(-9deg) skewX(4deg)}50%{transform:rotate(4deg) skewX(-3deg)}75%{transform:rotate(8deg) skewX(3deg)}}\n.gm-b-breathe{animation:gm-breathe 3s ease-in-out infinite}\n@keyframes gm-breathe{0%,100%{transform:scale(1)}50%{transform:scale(1.045,1.03)}}\n.gm-b-jump{animation:gm-jump 2s cubic-bezier(.2,.8,.3,1) infinite}\n@keyframes gm-jump{0%,50%,100%{transform:translateY(0) scale(1)}8%{transform:translateY(0) scale(1.06,.92)}20%{transform:translateY(-14px) scale(.95,1.06)}34%{transform:translateY(0) scale(1.04,.96)}}\n.gm-b-tilt{animation:gm-tilt 3s ease-in-out infinite}\n@keyframes gm-tilt{0%,100%{transform:rotate(0)}30%,70%{transform:rotate(-8deg) translateX(-2px)}}\n.gm-b-droop{animation:gm-droop 3.2s ease-in-out infinite}\n@keyframes gm-droop{0%,100%{transform:translateY(0)}50%{transform:translateY(3px) scale(1.01,.97)}}\n.gm-a.gm-b-beat{transform-origin:64px 64px;animation:gm-beat 1.2s ease-in-out infinite}\n@keyframes gm-beat{0%,40%,100%{transform:scale(1)}10%{transform:scale(1.16)}20%{transform:scale(1.02)}30%{transform:scale(1.1)}}\n.gm-b-flicker{animation:gm-flicker 1.1s ease-in-out infinite}\n@keyframes gm-flicker{0%,100%{transform:scale(1,1) skewX(0)}25%{transform:scale(.97,1.07) skewX(-3deg)}50%{transform:scale(1.02,.96) skewX(2deg)}75%{transform:scale(.98,1.05) skewX(3deg)}}\n.gm-a.gm-b-pop{transform-origin:64px 66px;animation:gm-pop 2.4s cubic-bezier(.4,1.5,.5,1) infinite}\n@keyframes gm-pop{0%{transform:rotate(0) scale(1)}35%{transform:rotate(72deg) scale(1.15)}55%,100%{transform:rotate(72deg) scale(1)}}\n.gm-b-hover{animation:gm-hover 2.4s ease-in-out infinite}\n@keyframes gm-hover{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}\n.gm-b-flash{animation:gm-flash 1.8s ease-in-out infinite}\n@keyframes gm-flash{0%,40%,62%,100%{opacity:1;transform:scale(1)}45%{opacity:.35;transform:scale(1.08)}50%{opacity:1}55%{opacity:.5}}\n.gm-b-wiggle{animation:gm-wiggle 2s ease-in-out infinite}\n@keyframes gm-wiggle{0%,50%,100%{transform:rotate(0)}10%{transform:rotate(-7deg)}20%{transform:rotate(7deg)}30%{transform:rotate(-5deg)}40%{transform:rotate(3deg)}}\n.gm-p-blink{animation:gm-blink 3.6s infinite}\n@keyframes gm-blink{0%,92%,100%{transform:scaleY(1)}95%{transform:scaleY(.1)}}\n.gm-p-pulse{animation:gm-pulse 1s ease-in-out infinite}\n@keyframes gm-pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.28)}}\n.gm-p-spin{animation:gm-spin 2.4s linear infinite}\n@keyframes gm-spin{to{transform:rotate(360deg)}}\n.gm-p-drip{animation:gm-drip 1.4s ease-in infinite}\n@keyframes gm-drip{0%{transform:translateY(0);opacity:1}70%{transform:translateY(10px);opacity:1}100%{transform:translateY(14px);opacity:0}}\n.gm-p-flow > path{stroke-dasharray:12 8;animation:gm-flow .6s linear infinite}\n@keyframes gm-flow{to{stroke-dashoffset:-20}}\n.gm-p-float{animation:gm-float 2.4s ease-out infinite}\n@keyframes gm-float{0%{transform:translate(0,0);opacity:1}80%{transform:translate(4px,-10px);opacity:0}81%{transform:translate(0,4px);opacity:0}100%{transform:translate(0,0);opacity:1}}\n.gm-p-halo{animation:gm-halo 2s ease-in-out infinite}\n@keyframes gm-halo{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}\n.gm-a.gm-p-wag{transform-origin:50% 0;animation:gm-wag .8s ease-in-out infinite}\n@keyframes gm-wag{0%,100%{transform:rotate(0)}25%{transform:rotate(12deg)}75%{transform:rotate(-12deg)}}\n.gm-p-twinkle{animation:gm-twinkle 1.6s ease-in-out infinite}\n.gm-p-twinkle.gm-t2{animation-delay:calc(var(--gm-d,0s) - .5s)}.gm-p-twinkle.gm-t3{animation-delay:calc(var(--gm-d,0s) - 1s)}\n@keyframes gm-twinkle{0%,100%{transform:scale(1) rotate(0)}50%{transform:scale(.55) rotate(45deg)}}\n.gm-p-look{animation:gm-look 3s ease-in-out infinite}\n@keyframes gm-look{0%,100%{transform:translateX(0)}25%,40%{transform:translateX(-14px)}60%,80%{transform:translateX(0)}}\n.gm-p-roll{animation:gm-roll 2.6s ease-in-out infinite}\n@keyframes gm-roll{0%,85%,100%{transform:translate(0,0)}30%{transform:translate(-5px,4px)}60%{transform:translate(5px,4px)}}\n.gm-p-draw > path{stroke-dasharray:80;animation:gm-draw 2.4s ease-in-out infinite}\n@keyframes gm-draw{0%,70%,100%{stroke-dashoffset:0}75%{stroke-dashoffset:80}95%{stroke-dashoffset:0}}\n.gm-a.gm-p-flame{transform-origin:50% 0;animation:gm-flame .3s ease-in-out infinite alternate}\n@keyframes gm-flame{from{transform:scaleY(1)}to{transform:scaleY(1.35)}}\n.gm-p-glow{animation:gm-glow 2s ease-in-out infinite;opacity:0}\n@keyframes gm-glow{0%,100%{opacity:0}50%{opacity:.55}}\n.gm-a.gm-p-hat{transform-origin:50% 100%;animation:gm-hat 1.6s ease-in-out infinite}\n@keyframes gm-hat{0%,60%,100%{transform:rotate(0)}20%{transform:rotate(-10deg)}40%{transform:rotate(6deg)}}\n.gm-p-confetti{animation:gm-confetti 1.6s ease-in infinite}\n@keyframes gm-confetti{0%{transform:translateY(0) rotate(0);opacity:1}80%{transform:translateY(16px) rotate(200deg);opacity:0}81%{transform:translateY(-6px);opacity:0}100%{transform:translateY(0);opacity:1}}\n.gm-p-confetti.gm-t2,.gm-p-float.gm-t2{animation-delay:calc(var(--gm-d,0s) - .6s)}.gm-p-confetti.gm-t3{animation-delay:calc(var(--gm-d,0s) - 1.1s)}\n/* new motions */\n.gm-a.gm-b-roll{transform-origin:64px 64px;animation:gm-roll2 1.4s ease-in-out infinite}\n@keyframes gm-roll2{0%,100%{transform:rotate(0)}25%{transform:rotate(-22deg)}50%{transform:rotate(0)}75%{transform:rotate(22deg)}}\n.gm-b-nudge{animation:gm-nudge 1.8s ease-in-out infinite}\n@keyframes gm-nudge{0%,50%,100%{transform:translateX(0)}20%{transform:translateX(5px)}35%{transform:translateX(-2px)}}\n.gm-a.gm-b-spin{transform-origin:64px 64px;animation:gm-spin 6s linear infinite}\n.gm-a.gm-b-ring{transform-origin:64px 14px;animation:gm-ring 1.6s ease-in-out infinite}\n@keyframes gm-ring{0%,60%,100%{transform:rotate(0)}10%{transform:rotate(14deg)}20%{transform:rotate(-12deg)}30%{transform:rotate(8deg)}40%{transform:rotate(-5deg)}}\n.gm-a.gm-b-flip{transform-origin:64px 64px;animation:gm-flip 2.2s ease-in-out infinite}\n@keyframes gm-flip{0%,40%,100%{transform:scaleX(1)}20%{transform:scaleX(.12)}}\n.gm-p-spin.gm-slow{animation-duration:9s}\n.gm-p-look2{animation:gm-look2 3.4s ease-in-out infinite}\n@keyframes gm-look2{0%,100%{transform:translateX(0)}40%,70%{transform:translateX(10px)}}\n.gm-p-puff{animation:gm-puff 1.2s ease-out infinite}\n@keyframes gm-puff{0%{transform:scale(.6);opacity:1}100%{transform:scale(1.3) translateY(4px);opacity:0}}\n.gm-p-crackL{animation:gm-crackL 2.4s ease-in-out infinite}.gm-p-crackR{animation:gm-crackR 2.4s ease-in-out infinite}\n@keyframes gm-crackL{0%,40%,100%{transform:translate(0,0) rotate(0)}60%,80%{transform:translate(-4px,2px) rotate(-6deg)}}\n@keyframes gm-crackR{0%,40%,100%{transform:translate(0,0) rotate(0)}60%,80%{transform:translate(4px,2px) rotate(6deg)}}\n.gm-a.gm-p-wave{transform-origin:50% 100%;animation:gm-wave 1.4s ease-in-out infinite}\n@keyframes gm-wave{0%,60%,100%{transform:rotate(0)}10%,30%{transform:rotate(-16deg)}20%,40%{transform:rotate(12deg)}}\n.gm-a.gm-p-flapL{transform-origin:100% 50%;animation:gm-flapL .5s ease-in-out infinite alternate}\n.gm-a.gm-p-flapR{transform-origin:0% 50%;animation:gm-flapR .5s ease-in-out infinite alternate}\n.gm-a.gm-p-flapL,.gm-a.gm-p-flapR{transform-box:fill-box}\n@keyframes gm-flapL{to{transform:scaleX(.55)}}@keyframes gm-flapR{to{transform:scaleX(.55)}}\n.gm-p-steam{animation:gm-float 2.2s ease-out infinite}\n.gm-p-rain{animation:gm-rain 1s linear infinite}\n@keyframes gm-rain{0%{transform:translateY(-6px);opacity:0}20%{opacity:1}100%{transform:translateY(14px);opacity:0}}\n.gm-p-flash{animation:gm-flash 1.6s ease-in-out infinite}\n.gm-p-sand{animation:gm-sand 1s linear infinite;stroke-dasharray:4 4}\n.gm-p-sand > path{stroke-dasharray:4 5;animation:gm-flow .5s linear infinite}\n@keyframes gm-sand{to{opacity:1}}\n.gm-p-hit{animation:gm-hit 2s cubic-bezier(.5,0,.2,1) infinite}\n@keyframes gm-hit{0%,60%,100%{transform:translate(0,0)}30%{transform:translate(14px,-14px)}40%{transform:translate(0,0)}48%{transform:translate(2px,-2px)}}\n.gm-p-draw2 > path{stroke-dasharray:120;animation:gm-draw2 3s ease-in-out infinite}\n@keyframes gm-draw2{0%,70%,100%{stroke-dashoffset:0}75%{stroke-dashoffset:120}98%{stroke-dashoffset:0}}\n.gm-a.gm-p-flag{transform-origin:0 50%;animation:gm-flag 1.4s ease-in-out infinite}\n@keyframes gm-flag{0%,100%{transform:skewY(0) scaleX(1)}50%{transform:skewY(-5deg) scaleX(.95)}}\n.gm-p-typing{animation:gm-typing 1.2s ease-in-out infinite}\n.gm-p-typing.gm-t2{animation-delay:calc(var(--gm-d,0s) - .9s)}.gm-p-typing.gm-t3{animation-delay:calc(var(--gm-d,0s) - .6s)}\n@keyframes gm-typing{0%,60%,100%{transform:translateY(0);opacity:.55}30%{transform:translateY(-6px);opacity:1}}\n.gm-p-flame.gm-t2,.gm-p-rain.gm-t2,.gm-p-twinkle.gm-t2{animation-delay:calc(var(--gm-d,0s) - .4s)}.gm-p-flame.gm-t3,.gm-p-rain.gm-t3,.gm-p-float.gm-t3{animation-delay:calc(var(--gm-d,0s) - .7s)}\n.gm-p-puff.gm-t2{animation-delay:calc(var(--gm-d,0s) - .6s)}.gm-p-steam.gm-t2{animation-delay:calc(var(--gm-d,0s) - 1.1s)}\n/* play modes: gm-loop (always), gm-hover (on hover/focus), gm-none (static) */\n.gm .gm-a,.gm .gm-a>*{animation-play-state:paused}\n.gm-loop .gm-a,.gm-loop .gm-a>*,\n.gm-hover:hover .gm-a,.gm-hover:hover .gm-a>*,\n.gm-trigger:hover .gm-hover .gm-a,.gm-trigger:hover .gm-hover .gm-a>*,\n.gm-trigger:focus-visible .gm-hover .gm-a,.gm-trigger:focus-visible .gm-hover .gm-a>*{animation-play-state:running}\n.gm-none .gm-a,.gm-none .gm-a>*{animation:none}\n.gm-none .gm-p-glow{opacity:0}\n@media (prefers-reduced-motion:reduce){.gm .gm-a,.gm .gm-a>*{animation:none!important}.gm .gm-p-glow{opacity:0}}\n";
